<?php
declare(strict_types=1);namespace Tests\Functional;use App\AppKernel;use App\Seeder;use RuntimeException;use Slim\App;use Slim\Psr7\Factory\ServerRequestFactory;use Slim\Psr7\Factory\StreamFactory;final class ApiResponse{public function __construct(public readonly int$status,public readonly array$headers,public readonly string$raw,public readonly mixed$json){}}final class FunctionalTestCase{private?App$app;private string$dbPath;private array$cookies=[];private int$assertions=0;private const USERS=['operator'=>'operator@example.test','admin'=>'admin@example.test','disabled'=>'disabled@example.test'];public function __construct(private readonly string$root){$this->dbPath=sys_get_temp_dir().'/system-functional-'.bin2hex(random_bytes(8)).'.sqlite';Seeder::reset($root,$this->dbPath);$this->app=AppKernel::create($root,['APP_ENV'=>'test','DB_PATH'=>$this->dbPath,'SESSION_COOKIE'=>'system_test_session']);}public function assertions():int{return$this->assertions;}public function close():void{$this->app=null;gc_collect_cycles();foreach([$this->dbPath,$this->dbPath.'-journal',$this->dbPath.'-wal',$this->dbPath.'-shm']as$p)if(is_file($p))unlink($p);}public function login(string$a,string$p='Password123!'):ApiResponse{if(!isset(self::USERS[$a]))throw new RuntimeException('Unknown actor: '.$a);$x=$this->request('POST','/api/auth/login',['email'=>self::USERS[$a],'password'=>$p]);if($x->status===200&&preg_match('/^system_test_session=([^;]+)/',$x->headers['Set-Cookie'][0]??'',$m))$this->cookies[$a]=rawurldecode($m[1]);return$x;}public function as(string$a,string$m,string$u,?array$b=null):ApiResponse{if(!isset($this->cookies[$a]))$this->status(200,$this->login($a),$a.' fixture login');return$this->request($m,$u,$b,$this->cookies[$a]);}public function request(string$m,string$u,?array$b=null,?string$c=null):ApiResponse{$q=(new ServerRequestFactory())->createServerRequest($m,$u);if($c!==null)$q=$q->withCookieParams(['system_test_session'=>$c]);if($b!==null)$q=$q->withHeader('Content-Type','application/json')->withBody((new StreamFactory())->createStream(json_encode($b,JSON_THROW_ON_ERROR)));$r=$this->app?->handle($q);if(!$r)throw new RuntimeException('Closed test app.');$raw=(string)$r->getBody();$json=str_contains($r->getHeaderLine('Content-Type'),'application/json')&&$raw!==''?json_decode($raw,true,512,JSON_THROW_ON_ERROR):null;return new ApiResponse($r->getStatusCode(),$r->getHeaders(),$raw,$json);}public function status(int$e,ApiResponse$r,string$l='status'):void{$this->same($e,$r->status,$l);}public function same(mixed$e,mixed$a,string$l='value'):void{$this->assertions++;if($e!==$a)throw new RuntimeException($l.': expected '.var_export($e,true).', got '.var_export($a,true));}public function true(bool$v,string$l='condition'):void{$this->assertions++;if(!$v)throw new RuntimeException($l.': expected true');}public function contains(string$n,string$h,string$l='text'):void{$this->assertions++;if(!str_contains($h,$n))throw new RuntimeException($l.': missing '.$n);}}
